    {"id":"id_clf_wan","espanol":"Tazón","tradicional":"碗","pinyin":"wǎn","zhuyin":"ㄨㄢˇ","categoria":"M","clasificador":"","radicales":[{"type":"text","value":"石 (shí - piedra)"},{"type":"text","value":"宛 (wǎn - cuenco)"}],"notas":"Clasificador contenedor para porciones de comida o sopa servidas en cuencos o tazones.","ejemplos":["我要一碗牛肉麵 — Quiero un tazón de fideos con carne de res","請給他一碗熱湯 — Por favor dale un tazón de sopa caliente"],"fechaCreacion":"2026-10-19","leccion":5,"posSymbol":"M","semanticTags":["measure"]}
